-- Table: accounting_bank_reconciliation_detail
-- Source: accounting_admin_db.sql (6. Accounting expense, reconciliation, and period closing)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS accounting_bank_reconciliation_detail (
    id                       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reconciliation_id        BIGINT NOT NULL REFERENCES accounting_bank_reconciliation(id) ON DELETE CASCADE,
    line_number              INTEGER NOT NULL CHECK (line_number > 0),
    transaction_date         DATE NOT NULL,
    reference_number         VARCHAR(100),
    description              TEXT,
    debit                    NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (debit >= 0),
    credit                   NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (credit >= 0),
    matched_journal_detail_id BIGINT REFERENCES accounting_journal_detail(id),
    status                   VARCHAR(20) NOT NULL DEFAULT 'unmatched'
                             CHECK (status IN ('matched', 'unmatched')),
    UNIQUE (reconciliation_id, line_number)
);
